CREATE TABLE `approval_edits` (
  `approval_edits_id` int NOT NULL AUTO_INCREMENT,
  `old_info` text NOT NULL,
  `new_info` text NOT NULL,
  `type` enum('Loan edit','Loan delete') NOT NULL,
  `id` varchar(200) NOT NULL,
  `summary` varchar(200) DEFAULT NULL,
  `state` enum('Initiated','recommended','Approved','Rejected') NOT NULL DEFAULT 'Initiated',
  `Initiated_by` varchar(200) NOT NULL,
  `Initiated_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `recommended_by` varchar(200) NOT NULL,
  `recommended_date` date NOT NULL,
  `recommend_comment` text NOT NULL,
  `approved_by` varchar(200) NOT NULL,
  `approved_date` date NOT NULL,
  `approval_comment` text NOT NULL,
  `recommed_reject_by` varchar(200) DEFAULT NULL,
  `recommed_reject_date` date DEFAULT NULL,
  `recommed_reject_comment` text,
  `approval_reject_by` varchar(200) DEFAULT NULL,
  `approval_reject_date` date DEFAULT NULL,
  `approval_reject_comment` text,
  `stamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`approval_edits_id`)
) ENGINE=MyISAM AUTO_INCREMENT=415 DEFAULT CHARSET=latin1;
