INSERT INTO `groups` VALUES (1,'458','Ku Anyamata',NULL,7,'<p>Ku Anyamata group is located in Mbayani and all members conducct business in the same place. The group requested a loan the second time. The chairman is Rose Nsoka, Grace Zambezi is the treasure and Martha Magalasi is the secretary.</p>','','ok','Null',83,'Active','2023-07-13 13:34:20'),(2,'575','Musipiwa',NULL,7,'<p>Musipiwa group is located in Mbayani market and all the members conduct thier business at the same place. Felia Banda is the chairperson, Tereza Moleni is the treasure and Shine Kazembe is the secretary.</p>','','ok','Null',83,'Active','2023-07-14 09:34:41'),(3,'607','Thandizo',NULL,7,'<p>Thandizo group is located in Lunzu market and all members conduct business at the same place. Chester Banda is the chairperson and Francis Muwisa is the treasure.</p>','','ok','Null',83,'Active','2023-07-14 10:08:34'),(4,'739','Mpira',NULL,7,'<p>Mpira group is located in Lunzu market and all memberes conduct business in the same place. Egfa Kaula is the chairpersson of the group and Joyce Bonongwe is the treasure.</p>','','ok','Null',83,'Active','2023-08-14 04:21:30'),(5,'768','Esinati',NULL,7,'<p>Esinati group is located in Lunzu market and all members conduct business in the same place. The chairperson of the group is Esinati Daniel and Thomoson Kachingwe is the treasure.</p>','','ok','Null',83,'Active','2023-08-14 04:41:36'),(6,'394','Miwawa',NULL,7,'<p>Miwawa group is located in Lunzu market and all members conduct business in the same place, Peter Bulla is the cahirperson and Tisungane is the treasure.</p>','','ok','Null',83,'Active','2023-08-14 05:36:02'),(7,'997','Patience',NULL,7,'<p>Patience group is located in Lunzu market and all members conduct there business in the same place. Maria Chigomire is the chairperson and Catherine Billiat is the treasure.</p>','','ok','Null',83,'Active','2023-08-14 06:15:27'),(8,'489','Ziyaya',NULL,7,'<p>Ziyaya group is located in Lunzu market and all members conduct 